/* one concrete "instantiation" per type, generated by a macro */
#define DEFINE_MAX(T, name) \
  static inline T name##_max(T a, T b) { return a > b ? a : b; }
DEFINE_MAX(int, i)
DEFINE_MAX(double, d)

/* C11: selection by the controlling expression's type, at compile time */
#define MAX(a, b) _Generic((a), int: i_max, double: d_max, default: i_max)(a, b)
